targets.root_selector:
(
  $cov := (
    $start := coverage.pages.start;
    $profiles := run.profiles;
    $entry := coverage.scenarios.entry;
    $root := $;
    $seen := $profiles.(
      $prof := $;
      $count($distinct($root.pages[profile = $prof and $count(path) = 1].(path[0])))
    );
    $all := $exists($entry) ? $entry >= $start * $count($profiles) : $count($seen[$ < $start]) = 0;
    $exact := $all or ($exists($entry) and $entry = $sum($seen));
    {
      "known": $exists($start) and $exists($profiles),
      "cut": $not($all),
      "rows": $exists($start) and $exists($profiles) ? [$map($profiles, function($prof, $i) {(
        $open := $all ? $start : $seen[$i];
        {
          "_k": "S", "profile": $prof,
          "Opened": ($exact ? "" : "≥ ") & $open & " of " & $start
            & ($start > 0 ? " (" & $round($open / $start * 100) & " %)" : "")
        }
      )})] : []
    }
  );
  $n := (
    $order := ["entry", "browse", "key-replaced", "reload"];
    $sc := coverage.scenarios;
    $exists($sc) and $type($sc) = "object" ? [$map(
      $sort($keys($sc), function($a, $b) {(
        $ia := $count($order[$ = $a]) > 0 ? $sum($map($order, function($o, $j) { $o = $a ? $j : 0 })) : 99;
        $ib := $count($order[$ = $b]) > 0 ? $sum($map($order, function($o, $j) { $o = $b ? $j : 0 })) : 99;
        $ia = $ib ? $a > $b : $ia > $ib
      )}),
      function($k) { { "_k": "N", "Scenario": $k, "_sv": $lookup($sc, $k) } }
    )] : []
  );
  $t := (
  $ch := coverage.checks;
  $mismatch := $exists($ch) ? $ch.mismatch : $exists(coverage.brokenLinksFound) ? coverage.brokenLinksFound : $count(problems);
  $exists(run) ? {
    "_k": "T",
    "_dur": (
      $s := $round(($toMillis(run.finishedAt) - $toMillis(run.startedAt)) / 1000);
      $s < 3600
        ? $floor($s / 60) & " min " & $formatNumber($s % 60, "00") & " s"
        : $floor($s / 3600) & " h " & $formatNumber($floor(($s % 3600) / 60), "00") & " min"
    ),
    "_stop": $cov.known ? ($cov.cut ? "Stopped early (limit)" : "Start pages all opened") : null,
    "Run · " & $fromMillis($toMillis(run.startedAt), "[MNn,3-3] [D01], [H01]:[m01] UTC"): $mismatch > 0 ? "Issues found" : "OK",
    "Links checked": coverage.links.checked,
    "Passed": $ch.pass,
    "Key lost or replaced": $ch.mismatch
  } : { "_k": "T", "Run": "No report (crashed or running)" }
);
  $v := (
  $routes := $join($map($sort($distinct(pages.problems[route and route != ""].route)), function($r) { "«" & $r & "»" }));
  $root := $;
  [pages.(
    $p := $;
    {
      "_k": "V", "Page": $p.page, "profile": $p.profile, "_dev": $p.profile,
      "Scenarios": $join($sort($distinct($root.pages[page = $p.page].scenarios)), ", "),
      "_v": 1, "_nc": $count($p.untested), "_rk": $routes
    }
  )]
);
  $p := (
  $compact := function($v) {
    $type($v) = "string" ? $v
    : $type($v) = "object" ? $join($each($v, function($x, $k) { $k & "=" & $x }), ", ")
    : $exists($v) and $type($v) != "null" ? $string($v) : "null"
  };
  [pages.(
    $p := $;
    $steps := $join($map($p.path, function($s, $i) { ($i + 1) & ". " & $s }), " | ");
    problems.{
      "_k": "P", "Page": $p.page, "profile": $p.profile, "route": route ? route : "—", "href": href ? href : "",
      "expected": expected ? expected : "", "actual": $compact(actual), "selector": selector ? selector : "",
      "checked": $compact(checked), "path": $steps ? $steps : "",
      "_p": 1, "_rk": "«" & (route ? route : "") & "»"
    }
  )]
);
  $u := (
  $site := ["qrHidden", "qrUnreadable", "pageGone"];
  [pages.(
    $p := $;
    untested.{
      "_k": "U", "Reason": reason ? reason : "",
      "Kind": reason in $site ? "not testable (site)" : "check failed (tool)",
      "_visit": $p.page & " " & $p.profile, "_n": 1, "Page": $p.page, "profile": $p.profile,
      "selector": selector ? selector : "", "detail": detail ? detail : ""
    }
  )]
);
  $append($append($append($append($append([$t], $v), $p), $u), $cov.rows), $n)
)
